import gurobipy as gp
from gurobipy import GRB
products = []
profit = {}
weight = {}
for rec in LEGACY_RECORDS:
    if rec['source'] == 'products.csv':
        pname = rec['values']['ProductName']
        products.append(pname)
        profit[pname] = int(rec['values']['Value'])
        weight[pname] = int(rec['values']['Weight'])
capacity = None
for rec in LEGACY_RECORDS:
    if rec['source'] == 'capacity.csv' and rec['values'].get('archive_revision_number') == '4':
        capacity = int(rec['values']['Capacity'])
if capacity is None:
    raise ValueError('No capacity found for archive_revision_number 4 in capacity.csv')
for pname in products:
    if pname not in profit or pname not in weight:
        raise ValueError(f'Missing profit or weight for product {pname}')
m = gp.Model('VehicleOrder')
x = m.addVars(products, lb=0, vtype=GRB.INTEGER, name='')
m.setObjective(gp.quicksum((profit[p] * x[p] for p in products)), GRB.MAXIMIZE)
m.addConstr(gp.quicksum((weight[p] * x[p] for p in products)) <= capacity, name='cap')
m.Params.MIPGap = 0.0001
m.optimize()
if m.Status == GRB.OPTIMAL:
    print(f'ObjVal: {m.ObjVal}')
    for v in m.getVars():
        print(f'{v.VarName}: {v.X}')
else:
    print(f'Solver status: {m.Status}')